NAME = 'GerTafel: German Tafelbibel (1911)'
BOOK = 'I Timothy'

CHAPTERS = {
    1: {
        1: 'Paulus, ein Apostel Jesu Christi, auf Befehl Gottes unseres Heilandes und Christus Jesus, Der unsere Hoffnung ist.',
        2: 'An Timotheus den rechtschaffenen Sohn im Glauben: Gnade, Barmherzigkeit, Friede von Gott unserem Vater und Jesus Christus unserem Herrn!',
        3: 'Wie ich dich ermahnt habe, in Ephesus zu bleiben, da ich auf der Reise nach Mazedonien war, um gewissen Leuten zu verwehren, daß sie nicht afterlehren,',
        4: 'Auch nicht Acht hätten auf Fabeln und auf Geschlechtsregister, die kein Ende haben und mehr zu Streitigkeiten führen als zu göttlicher Erbauung im Glauben.',
        5: 'Der Endzweck der Lehre ist ja: Liebe aus reinem Herzen und gutem Gewissen und ungeheucheltem Glauben;',
        6: 'Wovon einige abgewichen sind, und zu unnützem Geschwätz sich gewendet haben;',
        7: 'Wollen der Schrift Meister sein und verstehen nicht was sie sagen oder aufstellen.',
        8: 'Wir wissen aber, daß das Gesetz gut ist, wenn es einer gesetzmäßig anwendet.',
        9: 'Und so viel weiß ich, daß für den Gerechten kein Gesetz gegeben ist, sondern für die Ungerechten und Ordnungsfeinde, für Gottlose und Sünder, Unheilige und Ungeistliche, für Vater- und Muttermörder, Totschläger.',
        10: 'Für Hurer, Knabenschänder, Menschendiebe, Lügner, Meineidige und was sonst der gesunden Lehre zuwider läuft.',
        11: 'Nach dem Evangelium der Herrlichkeit des seligen Gottes, das mir anvertraut worden ist.',
        12: 'Und ich danke Dem, Der mir die Kraft dazu gegeben, unserem Herrn Jesus Christus, daß Er mich für treu erachtet und mich ins Amt gesetzt hat,',
        13: 'Mich, der ich vorher ein Lästerer, Verfolger und Schmäher war, aber ich fand Erbarmen, weil ich es unwissend im Unglauben tat.',
        14: 'Aber die Gnade unseres Herrn mit dem Glauben und der Liebe in Jesus Christus war um so überschwenglicher.',
        15: 'Das ist ja gewißlich wahr und ein teuer, wertes Wort, daß Jesus Christus in die Welt gekommen ist, die Sünder selig zu machen, unter denen ich der vornehmste bin.',
        16: 'Aber darum ist mir Barmherzigkeit widerfahren, daß an mir zuerst Jesus Christus erzeigte Seine Langmut, zum Vorbild denen, die an Ihn glauben würden zum ewigen Leben.',
        17: 'Aber dem König der Ewigkeiten, dem unvergänglichen, unsichtbaren, alleinigen Gott sei Ehre und Herrlichkeit von Ewigkeit zu Ewigkeit! Amen.',
        18: 'Dies Gebot empfehle ich dir, mein Sohn Timotheus, nach den vorausgegangen Prophezeiungen über dich, daß du in denselben kämpfest den guten Kampf,',
        19: 'Und habest einen guten Glauben, und ein gut Gewissen, welches gewisse Leute von sich gestoßen und am Glauben Schiffbruch gelitten haben,',
        20: 'Unter denen ist Hymenäus und Alexander, die ich dem Satan übergeben habe, auf daß sie gezüchtigt würden, nicht mehr zu lästern.',
    },
    2: {
        1: 'So ermahne ich nun, daß man vor allen Dingen zuerst tue Bitte, Gebet, Fürbitte, Danksagung für alle Menschen;',
        2: 'Für Könige und alle, die obenan stehen, auf daß wir ein geruhiges und stilles Leben führen, in aller Gottseligkeit und Ehrbarkeit.',
        3: 'Denn solches ist gut und wohlgefällig vor Gott, unserem Heiland,',
        4: 'Der will, daß allen Menschen geholfen werde, und sie zur Erkenntnis der Wahrheit kommen.',
        5: 'Denn es ist ein Gott, auch ein Mittler zwischen Gott und den Menschen, ein Mensch Jesus Christus,',
        6: 'Der Sich Selbst gegeben hat für alle zur Erlösung, daß es zu seiner Zeit bezeugt würde.',
        7: 'Wofür ich zum Herold und Apostel gesetzt bin ich sage die Wahrheit',
        8: 'So will ich nun, daß die Männer allerorten beten, indem sie heilige Hände aufheben, ohne Zorn und böse Gedanken.',
        9: 'Desgleichen sollen die Weiber mit anständigem Wesen, mit Zucht und Sittsamkeit sich schmücken, nicht mit künstlichem Kopfputz, mit Gold oder Perlen oder kostbarem Gewand,',
        10: 'Sondern, wie es sich ziemt für Weiber, die sich zur Gottseligkeit bekennen, durch gute Werke.',
        11: 'Ein Weib lerne in der Stille in aller Unterordnung.',
        12: 'Einem Weibe aber gestatte ich nicht, zu lehren, auch nicht, daß sie den Mann beherrsche, und sie soll sich ruhig verhalten.',
        13: 'Denn Adam wurde zuerst geschaffen, hernach Eva.',
        14: 'Auch wurde Adam nicht verführt, sondern das Weib ließ sich verführen und hat die Übertretung begangen.',
        15: 'Sie wird aber selig werden durch Kindergebären, wenn sie im Glauben und in der Liebe und in der Heiligung und Sittsamkeit beharrt.',
    },
    3: {
        1: 'Das ist gewißlich wahr: So einer ein Bischofsamt begehrt, der begehrt ein köstlich Werk.',
        2: 'Ein Bischof soll unsträflich sein, eines Weibes Mann, nüchtern, besonnen, ehrbar, gastfrei, lehrfähig;',
        3: 'Kein Weinsäufer, kein Raufbold,',
        4: 'Der seinem eigenen Hause wohl vorsteht und gehorsame Kinder hat, mit aller Ehrbarkeit.',
        5: 'So jemand seinem eigenen Hause nicht weiß vorzustehen, wie wird er für eine Gemeinde Gottes sorgen?',
        6: 'Kein Neuling, auf daß er sich nicht aufblase und nicht dem Urteil des Teufels verfalle.',
        7: 'Er muß aber auch ein gutes Zeugnis haben von denen draußen, auf daß er nicht der Lästerung anheimfalle, und in den Fallstrick des Teufels gerate;',
        8: 'Desgleichen sollen die Diakone ehrbar sein, nicht doppelzüngig, nicht vielem Weintrinken ergeben, nicht nach schändlichem Gewinn trachten;',
        9: 'Sie sollen das Geheimnis des Glaubens in reinem Gewissen bewahren.',
        10: 'Auch sollen sie erst erprobt werden, dann in das Amt treten, wenn sie unsträflich waren.',
        11: 'Die Weiber sollen gleichermaßen ehrbar sein, keine Lästerzungen, nüchtern und treu in allen Dingen.',
        12: 'Die Diakone sollen ein Weib haben, Haus und Kinder in Zucht halten.',
        13: 'Wenn sie ihrem Amte wohl vorstehen, gelangen sie auf eine Ehrenstufe und zu vieler Zuversicht im Glauben in Jesus Christus.',
        14: 'Solches schreibe ich an dich und hoffe in nächster Zeit zu dir zu kommen;',
        15: 'So ich aber verzöge, sollst du wissen, wie du dich zu verhalten hast im Hause Gottes, das ist die Gemeinde des lebendigen Gottes, als ein Pfeiler und eine Stütze der Wahrheit.',
        16: 'Und anerkanntermaßen ist das Geheimnis der Gottseligkeit groß: Gott ist im Fleisch geoffenbart, gerechtfertigt im Geist, erschaut von Engeln, gepredigt unter Heiden, geglaubt in der Welt, aufgenommen in die Herrlichkeit.',
    },
    4: {
        1: 'Der Geist sagt ausdrücklich, daß in späteren Zeiten etliche vom Glauben abfallen und Irrgeistern und Lehren der Teufel anhangen werden,',
        2: 'Mittelst der Heuchelei von Lügenrednern, die in ihrem eigenen Gewissen gebrandmarkt sind,',
        3: 'Die verbieten ehelich zu werden und gewisse Speisen zu genießen, die doch Gott geschaffen hat, daß sie mit Danksagung genossen werden von den Gläubigen und von denen, so die Wahrheit erkannt haben.',
        4: 'Denn alles, was Gott erschaffen hat, ist gut, und nichts verwerflich, so es mit Danksagung empfangen wird;',
        5: 'Denn es wird geheiligt durch das Wort Gottes und Gebet.',
        6: 'Wenn du den Brüdern solches vorhältst, so wirst du ein guter Diener Jesu Christi sein, auferzogen in den Worten des Glaubens und der rechten Lehre, der du gefolgt bist.',
        7: 'Habe nichts zu schaffen mit ungeistlichen Altweiberfabeln, übe dich selbst aber in der Gottseligkeit.',
        8: 'Die leibliche Übung ist wenig nütze, aber die Gottseligkeit ist zu allen Dingen nütze und hat die Verheißung dieses und des zukünftigen Lebens.',
        9: 'Dies ist gewißlich wahr, und ein teuer, wertes Wort.',
        10: 'Denn dafür mühen wir uns und lassen uns schmähen, daß wir auf den lebendigen Gott gehofft, Welcher ist der Heiland aller Menschen, besonders der Gläubigen.',
        11: 'Solches gebiete und lehre.',
        12: 'Niemand müsse deine Jugend verachten; sondern werde ein Vorbild der Gläubigen in der Lehre, im Wandel, in der Liebe, im Geist, im Glauben, in der Keuschheit.',
        13: 'Halte an mit Lesen, Ermahnen, mit Lehren, bis ich komme.',
        14: 'Laß nicht unbenützt die Gabe in dir, die dir gegeben ist, für Weissagung mit Handauflegung der Ältesten.',
        15: 'Dies lasse dir angelegen sein, dabei bleibe, auf daß dein Fortschritt in allen Dingen sichtbar werde.',
        16: 'Habe Acht auf dich selbst, und auf die Lehre! Verbleibe dabei; denn wenn du solches tust, wirst du dir selbst und denen, die dich hören, zum Heile werden.',
    },
    5: {
        1: 'Fahre nicht aus gegen einen Alten, sondern ermahne ihn als einen Vater, jüngere als Brüder,',
        2: 'Alte Frauen als Mütter, jüngere als Schwestern, in aller Sittsamkeit.',
        3: 'Ehre Witwen, die rechte Witwen sind.',
        4: 'So aber eine Witwe Kinder oder Enkel hat, so sollen diese zuerst lernen ihr eigen Haus Gott wohlgefällig bestellen und ihren Eltern ihre Liebe vergelten, denn dies ist vor Gott angenehm.',
        5: 'Die aber eine rechte Witwe und vereinsamt ist, hat ihre Hoffnung auf Gott gesetzt und beharrt in Bitten und Gebeten Tag und Nacht.',
        6: 'So sie aber in Wollüsten lebt, ist sie lebendig tot.',
        7: 'Solches gebiete, auf daß sie untadelhaft leben.',
        8: 'Wenn aber einer die Seinen, sonderlich seine Hausgenossen, nicht versorgt, der hat den Glauben verleugnet und ist ärger als ein Ungläubiger.',
        9: 'Nimm eine Witwe in die Zahl auf, die nicht unter sechzig Jahren,',
        10: 'Ihrem Manne treu geblieben ist, und das Zeugnis guter Werke hat, wenn sie Kinder auferzogen, gastfrei gewesen ist, Heiligen die Füße gewaschen, Bedrängten Handreichung getan hat und jeglichem guten Werke nachgekommen ist.',
        11: 'Die jungen Witwen aber halte fern; denn wenn sie lüstern geworden sind wider Christus, so wollen sie freien,',
        12: 'Und fallen in Verantwortung, daß sie das erste Versprechen gebrochen haben.',
        13: 'Auch sind sie lässig, lernen umlaufen in den Häusern, und tun nicht nur nichts, sondern sind auch schwatzhaft und fürwitzig und reden, was sie nicht sollten.',
        14: 'Ich will, daß die Jüngeren freien, Kinder haben, einem Haushalt vorstehen, dem Widersacher keinen Anlaß zur Lästerung geben.',
        15: 'Denn schon sind etliche zurückgewichen, dem Satan nach.',
        16: 'Wenn ein Gläubiger oder eine Gläubige Witwen hat, so sollen sie für sie sorgen, und die Gemeinde nicht beschweren, auf daß sie denen, so rechte Witwen sind, genügen mögen.',
        17: 'Die Ältesten, die würdig vorstehen, halte man doppelt in Ehren, absonderlich die, so in Wort und Lehre arbeiten.',
        18: 'Denn die Schrift sagt: Du sollst dem Ochsen, der da drischt, nicht das Maul verbinden. Und: Der Arbeiter ist seines Lohnes wert.',
        19: 'Gegen einen Ältesten nimm keine Klage an, außer vor zwei oder drei Zeugen.',
        20: 'Die Fehlenden weise zurecht vor allen, auf daß auch die anderen Furcht haben.',
        21: 'Ich beschwöre dich vor Gott und dem Herrn Jesus Christus und den auserwählten Engeln, daß du solches beobachtest, ohne Vorurteil und nichts tust aus Gunst.',
        22: 'Lege niemand zu bald die Hände auf, und mache dich nicht fremder Sünden teilhaftig. Halte dich selber keusch.',
        23: 'Trinke nicht mehr bloß Wasser, sondern nimm ein wenig Wein wegen deines Magens und deiner häufigen Anfälle.',
        24: 'Einiger Menschen Sünden sind offenbar vor dem Gericht, andere kommen erst zutage durch dasselbe.',
        25: 'Desgleichen sind auch gute Werke schon bekannt, und die anderen können nicht verborgen bleiben.',
    },
    6: {
        1: 'Die Knechte, die unter dem Joch sind, sollen ihre Herren aller Ehre wert erachten, auf daß nicht der Name Gottes und die Lehre verlästert werden.',
        2: 'Die aber gläubige Herren haben, sollen dieselben nicht verachten, weil sie Brüder sind, sondern um so mehr dienstwillig sein, weil sie gläubig und geliebt und der Gnade teilhaftig sind. Solches lehre und ermahne dazu.',
        3: 'So jemand anders lehrt und bleibt nicht bei den heilsamen Worten unseres Herrn Jesus Christus und bei der Lehre der Gottseligkeit,',
        4: 'Der ist verblendet und weiß nichts, sondern siecht an Streitfragen und Wortkämpfen, aus denen entspringt Neid, Streitsucht, Lästerung, böser Argwohn,',
        5: 'Unnütze Wortzänkereien von Menschen, deren Verstand verschroben und der Wahrheit verschlossen ist, die da meinen, Gottseligkeit sei ein Gewerbe. Halte dich ferne von ihnen.',
        6: 'Es ist aber ein großer Gewinn um die Gottseligkeit, die sich genügen läßt.',
        7: 'Denn wir haben nichts in die Welt gebracht, und offenbar ist, daß wir auch nichts mit hinausnehmen können.',
        8: 'Wenn wir aber Nahrung und Kleidung haben, so lasset uns daran begnügen.',
        9: 'Die da reich werden wollen, fallen in Versuchung und Stricke und viel törichte und schädliche Lüste, welche die Menschen ins Elend und Verderben stürzen,',
        10: 'Denn Geiz ist eine Wurzel alles Übels; diejenigen, die geldgierig und vom Glauben irre gegangen sind, haben sich selbst viele Schmerzen bereitet.',
        11: 'Aber du, Gottesmensch, fliehe solches, jage nach der Gerechtigkeit, der Gottseligkeit, dem Glauben, der Liebe, der Beharrlichkeit, der Sanftmut.',
        12: 'Kämpfe den guten Kampf des Glaubens, erfasse das ewige Leben, für das du berufen bist und bekannt hast das gute Bekenntnis vor vielen Zeugen.',
        13: 'Ich gebiete dir vor Gott, Der alles lebendig macht, und vor Jesus Christus, Der vor Pontius Pilatus das gute Bekenntnis bezeugt hat,',
        14: 'Daß du haltest das Gebot unbefleckt, untadelhaft bis auf die Erscheinung unseres Herrn Jesus Christus;',
        15: 'Welche zu Seiner Zeit zeigen wird der selige und alleinige Gewalthaber, der König der Könige und der Herr der Herren.',
        16: 'Der allein Unsterblichkeit hat, Der in unzugänglichem Lichte wohnt, Den kein Mensch gesehen hat, noch sehen kann, Ihm sei Ehre und ewige Herrschaft! Amen.',
        17: 'Den Reichen dieser Welt gebiete nicht hochmütig zu sein, noch Hoffnung zu setzen auf den unsicheren Reichtum, sondern auf den lebendigen Gott, Der uns alles reichlich zum Genusse darbietet;',
        18: 'Daß sie Gutes tun, reich werden an guten Werken, freigebig, mitteilsam seien,',
        19: 'Und sich Schätze sammeln als guten Grund für die Zukunft, auf daß sie das wahre Leben erfassen.',
        20: 'O Timotheus, bewahre, was dir anvertraut ist, und mache dir nichts zu schaffen mit den gottlosen, leeren Reden und Streitfragen der fälschlich sogenannten Wissenschaft,',
        21: 'Die etliche vorgeben und vom Glauben abgewichen sind. Die Gnade sei mit euch! Amen.',
    },
}
